using Mono.Cecil;using Mono.Cecil.Cil;using System.Text.Json;using System.Security.Cryptography;
using var a=AssemblyDefinition.ReadAssembly(args[0]);using var b=AssemblyDefinition.ReadAssembly(args[1]);
IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> types){foreach(var t in types){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
string Body(MethodDefinition m)=>!m.HasBody?"none":string.Join("|",m.Body.Instructions.Select(i=>i.OpCode+":"+(i.Operand is Instruction target?m.Body.Instructions.IndexOf(target).ToString():i.Operand?.ToString())))+string.Join("|",m.Body.Variables.Select(v=>v.VariableType.FullName))+string.Join("|",m.Body.ExceptionHandlers.Select(e=>e.HandlerType+":"+m.Body.Instructions.IndexOf(e.TryStart)+":"+m.Body.Instructions.IndexOf(e.HandlerStart)));
var old=Types(a.MainModule.Types).SelectMany(t=>t.Methods).ToDictionary(m=>m.FullName);var current=Types(b.MainModule.Types).SelectMany(t=>t.Methods).ToDictionary(m=>m.FullName);var changed=old.Keys.Where(n=>!current.ContainsKey(n)||Body(old[n])!=Body(current[n])).ToArray();var added=current.Keys.Except(old.Keys).ToArray();var fields=Types(a.MainModule.Types).SelectMany(t=>t.Fields).Select(f=>f.FullName).SequenceEqual(Types(b.MainModule.Types).SelectMany(t=>t.Fields).Select(f=>f.FullName));string Res(Resource r)=>r is EmbeddedResource e?r.Name+Convert.ToHexString(SHA256.HashData(e.GetResourceData())):r.Name;var resources=a.MainModule.Resources.Select(Res).SequenceEqual(b.MainModule.Resources.Select(Res));bool refs=a.MainModule.AssemblyReferences.Select(r=>r.FullName).SequenceEqual(b.MainModule.AssemblyReferences.Select(r=>r.FullName));bool passed=changed.Length==2&&changed.All(n=>n.Contains("::PushMovementToUndoList(")||n.Contains("::PushRotationToUndoList("))&&added.Length==1&&added[0].Contains("::HasRecordedPlacementState(")&&fields&&resources&&refs;
var report=new{passed,originalMethods=old.Count,unchangedOriginalMethods=old.Count-changed.Length,changed,added,fieldsUnchanged=fields,resourcesUnchanged=resources,assemblyReferencesUnchanged=refs};File.WriteAllText(args[2],JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(report));if(!passed)Environment.ExitCode=1;
